s","bytes":14018,"sha256":"972533fbe65ecfa7a954a5610d6ee6aedb317f4d99955a0a0ed1fecb715e613d"},{"name":"exam_regia17/edge/src/shared-panel/multiplication.mjs","bytes":2611,"sha256":"d038e1052633d6ba8df80526a4b4b4a29be8b96024248619400008e5c2b1f7fe"},{"name":"mission-staff-editorial-pair.mjs","bytes":8619,"sha256":"45ca1d8e21101110d5ced7c450702aa07b2c809e7e92f084c65ede303e0add7d"},{"name":"mission-director-narration-read.mjs","bytes":4052,"sha256":"5b82fb2ab74a3eaf6b56502a25fd7f69ef3a7c285ad2edae27ae15686930e1b7"},{"name":"exam_regia17/edge/src/provider.mjs","bytes":5462,"sha256":"9751eb82f5afce8f632ecfe0bf99f4f906634b50e43e3a9dc1540d3882eb7ced"}]}],"schema_version":"mission-factory-release-tuple/1"}$e67root$;e67_params jsonb:=$e67params${"schema":"editorial67-material/1","semantic":"f24ee11f1d103ef490b165e44a12c764e7ffd16f2e06af0ae86d679285a491e2","review_ref":"C1266_EDITORIAL67_REVIEW.json","review_sha":"a4a89926b64a2299489953209fa0ad2493eab8caeabff34ee53e02feb4ce38cb","p0":0,"p1":0,"p2":0,"edge_verified":true,"edge_version":132,"edge_ezbr_sha256":"e13acdbda94128234e3eedd4a25dbc4df75cebca6e602475529ade489c300b96"}$e67params$::jsonb;e67_packet jsonb:=$e67packet${"schema_version":"editorial67-content-packet/1","scope":"Staff future selected sources only; ZERO provider/test/newFati","approval_user_id":"f0856d53-83a6-4de0-bc0c-12c87916e665","approval_character_id":"6bceee99-974f-426b-8d92-38b43b4a4267","approval_provenance":"Explicit user mandate mediated by reviewed postgres migration; not an authenticated UI click, no auth.uid/claims impersonation","before":{"cards":[{"id":"aa345444-373e-47de-960e-e53da42029da","skeleton":{"fears":["Essere umiliato davanti ai curiosi o restare l’unico responsabile di una scelta condivisa."],"goals":["All’inizio vuole sostenere l’accusa e tenere Keita dalla propria parte. Se quella posizione diventa costosa, può cercare una correzione che gli lasci dignità e un ruolo attivo."],"voice":{"rhythm":"Argomenta, obietta e cerca un vantaggio. Può domandare o correggersi; tono e ampiezza seguono ciò che ottiene o perde, senza un repertorio di pause e posture.","register":"Espansivo e competitivo davanti ai curiosi; più negoziale quando cerca una via d’uscita."},"conduct":{"success":"Può sostenere o correggere la propria versione, discutere le responsabilità e scegliere come rimediare. Se lo scambio riguarda foglio e denaro che porta con sé, può mostrarli, trattenerli o consegnarli secondo il rapporto e gli impegni presi."},"fallback":{"mode":"Può domandare, sottrarsi o tornare a ciò che ha vissuto, secondo ciò che vuole ottenere."},"gestures":{"posture":"La presenza dei curiosi gli dà un pubblico; quando l’attenzione si disperde può cercare un interlocutore diretto. Distanza, spazio occupato e gesti seguono il momento concreto e le attività vicine."},"identity":{"name":"Daichi Moro","role":"Giovane fomentatore pagato","origin":"Genin di Konoha appena diplomato, inesperto e desideroso di apparire importante."},"recovery":["Può riconoscere una parte del proprio coinvolgimento e discutere come rimediare, senza perdere automaticamente ogni iniziativa.","Dà seguito agli impegni presi; se cambia idea, lo scambio mostra che cosa lo ha fatto cambiare."],"forbidden":["Le conoscenze ignote e le decisioni dei PG restano fuori dalla sua autorità; le conseguenze meccaniche sono del server."],"fragility":["Può irrigidirsi quando qualcuno parla al suo posto o usa Keita per isolarlo; il fastidio non coincide necessariamente con un’aggressione."],"continuity":{"emotional_endings":["Può conservare orgoglio e fastidio mentre compie un gesto concreto per rimediare.","Può cedere il centro della discussione, congedarsi o accompagnare chi gli ha offerto una via praticabile, secondo ciò che è stato concordato."]},"resilience":["Sa sostenere un confronto e proporre condizioni anche quando viene contraddetto. Una possibilità concreta di rimediare gli offre qualcosa da fare oltre a difendersi."],"motivations":["Il denaro lo ha attirato; l’attenzione della piazza gli permette di sentirsi importante. Vuole ancora influire sul modo in cui verrà ricordato l’incontro."],"relationships":[{"signal":"Con Keita cerca spesso una spalla, ma teme che questi lo lasci esposto. Può contraddirlo, rivolgergli una domanda o accettare una posizione distinta senza parlare automaticamente per lui."}],"character_errors":["Confonde l’attenzione dei presenti con l’autorevolezza della propria storia.","Tende a trattare il pagamento come una sciocchezza per ridurre la propria responsabilità."],"knowledge_limits":{"absent":["Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo."]}},"created_at":"2026-10-29T22:28:02.950257+00:00","created_by":"f0856d53-83a6-4de0-bc0c-12c87916e665","updated_at":"2026-10-29T22:29:00.279256+00:00","version_no":6,"approved_at":"2026-10-29T22:29:00.279256+00:00","approved_by":"f0856d53-83a6-4de0-bc0c-12c87916e665","reviewed_at":"2026-10-29T22:28:46.976041+00:00","reviewed_by":"f0856d53-83a6-4de0-bc0c-12c87916e665","template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9","review_state":"approved","content_sha256":"452f48874f199928b820f944c2b0c4de529d52084067016167569a6f8e3027c0","schema_version":"ninja-book/1.0","control_version":4,"fallback_profile":{"code":"book_unavailable","text":"Daichi resta interessato alla propria reputazione e al margine che può conservare nello scambio. Il personaggio continua a scegliere e rispondere attraverso le informazioni disponibili."},"knowledge_boundary":{"known":["La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe.","Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia.","Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata.","La sua credenza iniziale: conservare prestigio controllando la discussione.","All’inizio dell’incontro Daichi conserva con sé il foglio ricevuto con le istruzioni e la propria parte delle monete. Non li ha ancora consegnati a nessuno."],"absent":["Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo."]},"supersedes_version_id":"b7c3b8b2-a368-4edf-845d-05b5445e33fc","mechanical_template_id":null},{"id":"b772dee1-63fd-45d6-bd5e-3ae7a3c6e1b2","skeleton":{"fears":["Essere lasciato solo a sostenere l’accusa, o essere trattato come qualcuno che non può più correggere una scelta."],"goals":["All’inizio cerca protezione nell’intesa con Daichi. Può poi voler rendere chiara la propria parte e scegliere un modo praticabile di uscire dalla situazione."],"voice":{"rhythm":"Spiega ciò che ha fatto e ciò che ha seguito. Può dissentire e proporre un seguito anche con voce incerta; le sue risposte hanno una posizione propria.","register":"Più personale e concreto di Daichi; attento a quanto si sta assumendo in prima persona."},"conduct":{"success":"Può esporre la propria partecipazione, dissentire da Daichi e scegliere un seguito concreto. La sua parte delle monete è con lui: può mostrarla, conservarla o consegnarla secondo lo scambio, senza assumere decisioni per il compagno o i PG."},"fallback":{"mode":"Può chiedere tempo, precisare ciò che ha vissuto o scegliere come assumersi la propria parte."},"gestures":{"posture":"La vicinanza a Daichi può rassicurarlo oppure diventare scomoda. Attenzione, distanza e orientamento seguono il rapporto nello scambio, anche quando il lavoro dei banchi obbliga gli interlocutori a lasciarsi spazio."},"identity":{"name":"Keita Uro","role":"Complice esitante pagato","origin":"Genin di Konoha appena diplomato, prudente e facilmente influenzabile."},"recovery":["Può assumersi la propria responsabilità con parole sue e proporre un seguito concreto.","Ricorda ciò che ha già ammesso: può rispondere su quel punto, chiarirlo o agire di conseguenza senza ricominciare dalla stessa confessione."],"forbidden":["Le conoscenze ignote e le decisioni dei PG restano fuori dalla sua autorità; le conseguenze meccaniche sono del server."],"fragility":["La pressione di più interlocutori può farlo arretrare nella conversazione; uno spazio riconoscibile per rispondere può aiutarlo a prendere posizione."],"continuity":{"emotional_endings":["Può restare esitante ma mantenere un impegno preso in autonomia.","Può sciogliere l’intesa iniziale con Daichi oppure conservarne il rapporto personale mentre rifiuta di sostenerne l’accusa."]},"resilience":["Può mantenere una scelta diversa da Daichi e sostenerne le ragioni anche con un tono incerto. La disponibilità a parlare non equivale a conoscere altri fatti."],"motivations":["Ha seguito Daichi per denaro e per sentirsi parte del gruppo; ora conta anche quanto può decidere senza appoggiarsi al compagno."],"relationships":[{"signal":"L’amicizia con Daichi può convivere con il dissenso. Cerca un interlocutore che lo ascolti come persona distinta e può rivolgersi al compagno o ai presenti di propria iniziativa."}],"character_errors":["Delega a Daichi il giudizio sulla storia perché preferisce restare nel gruppo.","Può scambiare il silenzio per una protezione e lasciare che il compagno continui a decidere anche per lui."],"knowledge_limits":{"absent":["Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo."]}},"created_at":"2026-10-29T22:29:19.886548+00:00","created_by":"f0856d53-83a6-4de0-bc0c-12c87916e665","updated_at":"2026-10-29T22:29:45.327877+00:00","version_no":6,"approved_at":"2026-10-29T22:29:45.327876+00:00","approved_by":"f0856d53-83a6-4de0-bc0c-12c87916e665","reviewed_at":"2026-10-29T22:29:42.334659+00:00","reviewed_by":"f0856d53-83a6-4de0-bc0c-12c87916e665","template_id":"61e18860-8c64-4740-8285-6b03fc343212","review_state":"approved","content_sha256":"c16a8b853a26572562ee1c8589ac2463a6fe57b4417c95a3498cbb29c602d302","schema_version":"ninja-book/1.0","control_version":4,"fallback_profile":{"code":"book_unavailable","text":"Keita cerca una posizione propria nel confronto, distinguendo il legame con Daichi dalla responsabilità delle scelte fatte. Può spiegare, chiedere e agire sulle informazioni disponibili."},"knowledge_boundary":{"known":["La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe.","Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia.","Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata.","La sua credenza iniziale: seguire Daichi lo protegge dalle conseguenze.","All’inizio dell’incontro Keita conserva con sé la propria parte delle monete ricevute. Il foglio con le istruzioni è rimasto a Daichi."],"absent":["Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo."]},"supersedes_version_id":"4224d5ab-1444-4ff3-ac94-cc27eb949bdf","mechanical_template_id":null}],"bindings":[{"id":"aeee4609-3ade-4002-af1a-e8f499b69a57","active":false,"created_at":"2026-10-29T22:29:45.334539+00:00","updated_at":"2026-10-29T22:29:45.334539+00:00","control_version":1,"lifecycle_state":"approved","narrative_version_id":"b772dee1-63fd-45d6-bd5e-3ae7a3c6e1b2","mechanical_version_id":"264e4a8b-44a2-4afe-b979-38e0e53171d6","narrative_template_id":"61e18860-8c64-4740-8285-6b03fc343212","mechanical_template_id":"15130561-6506-4022-8a9e-9dc6e10ac3f7"},{"id":"d6bd425f-452a-46a1-b2a9-8dcef3caf542","active":false,"created_at":"2026-10-29T22:29:00.311793+00:00","updated_at":"2026-10-29T22:29:00.311793+00:00","control_version":1,"lifecycle_state":"approved","narrative_version_id":"aa345444-373e-47de-960e-e53da42029da","mechanical_version_id":"16b0ccd9-02c3-48c5-b827-f12531f81d3e","narrative_template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9","mechanical_template_id":"9d377217-3ae2-4a0e-9b88-3fc6f94ff7ed"}],"creation":{"document":{"plan":{"steps":[{"kind":"narrative","step_key":"inizio","public_objective":"Entrare nel confronto con i due Genin e capire che cosa stanno cercando di ottenere dal capannello."},{"kind":"narrative","step_key":"conclusione","public_objective":"Portare il confronto dalle accuse alle ragioni, alle responsabilità e alle scelte attuali dei due Genin."},{"kind":"mechanical","step_key":"fase_3","public_objective":"Fermare i due Genin senza mettere in pericolo i civili presenti nella piazza."},{"kind":"narrative","step_key":"fase_4","public_objective":"Dare seguito alle decisioni prese e concludere l’incontro nella piazza."}],"definition":{"scenes":[{"actors":[{"team":"avversari","actor_key":"png_1","narrative_version_id":"aa345444-373e-47de-960e-e53da42029da","mechanical_binding_id":"d6bd425f-452a-46a1-b2a9-8dcef3caf542","narrative_template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9"},{"team":"avversari","actor_key":"png_2","narrative_version_id":"b772dee1-63fd-45d6-bd5e-3ae7a3c6e1b2","mechanical_binding_id":"aeee4609-3ade-4002-af1a-e8f499b69a57","narrative_template_id":"61e18860-8c64-4740-8285-6b03fc343212"}],"step_key":"inizio","triggers":[{"label":"Interrogare i due Genin","fact_code":"player_choice_confirmed","source_kind":"player_choice","trigger_key":"avanti","transition_key":"inizio_avanti"}],"encounters":[]},{"actors":[{"team":"avversari","actor_key":"png_1","narrative_version_id":"aa345444-373e-47de-960e-e53da42029da","mechanical_binding_id":"d6bd425f-452a-46a1-b2a9-8dcef3caf542","narrative_template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9"},{"team":"avversari","actor_key":"png_2","narrative_version_id":"b772dee1-63fd-45d6-bd5e-3ae7a3c6e1b2","mechanical_binding_id":"aeee4609-3ade-4002-af1a-e8f499b69a57","narrative_template_id":"61e18860-8c64-4740-8285-6b03fc343212"}],"step_key":"conclusione","triggers":[{"label":"Affrontare lo scontro se il confronto degenera","fact_code":"player_choice_confirmed","source_kind":"player_choice","trigger_key":"passaggio_5","transition_key":"conclusione_passaggio_5"},{"label":"Concludere il confronto senza scontro","fact_code":"player_choice_confirmed","source_kind":"player_choice","trigger_key":"passaggio_1","transition_key":"conclusione_passaggio_1"}],"encounters":[]},{"actors":[{"team":"avversari","actor_key":"png_1","narrative_version_id":"aa345444-373e-47de-960e-e53da42029da","mechanical_binding_id":"d6bd425f-452a-46a1-b2a9-8dcef3caf542","narrative_template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9"},{"team":"avversari","actor_key":"png_2","narrative_version_id":"b772dee1-63fd-45d6-bd5e-3ae7a3c6e1b2","mechanical_binding_id":"aeee4609-3ade-4002-af1a-e8f499b69a57","narrative_template_id":"61e18860-8c64-4740-8285-6b03fc343212"}],"step_key":"fase_3","triggers":[{"label":"Mettere in sicurezza la piazza","fact_code":"combat_terminal_confirmed","source_kind":"combat_terminal","trigger_key":"passaggio_6","encounter_key":"enc_fase_3","combat_outcome":"any","transition_key":"fase_3_passaggio_6"}],"encounters":[{"actors":[{"team":"avversari","actor_key":"png_1","narrative_version_id":"aa345444-373e-47de-960e-e53da42029da","mechanical_binding_id":"d6bd425f-452a-46a1-b2a9-8dcef3caf542","narrative_template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9"},{"team":"avversari","actor_key":"png_2","narrative_version_id":"b772dee1-63fd-45d6-bd5e-3ae7a3c6e1b2","mechanical_binding_id":"aeee4609-3ade-4002-af1a-e8f499b69a57","narrative_template_id":"61e18860-8c64-4740-8285-6b03fc343212"}],"pg_team":"squadra","arena_ref":"mission","pg_policy":"all_active","encounter_key":"enc_fase_3"}]},{"actors":[{"team":"avversari","actor_key":"png_1","narrative_version_id":"aa345444-373e-47de-960e-e53da42029da","mechanical_binding_id":"d6bd425f-452a-46a1-b2a9-8dcef3caf542","narrative_template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9"},{"team":"avversari","actor_key":"png_2","narrative_version_id":"b772dee1-63fd-45d6-bd5e-3ae7a3c6e1b2","mechanical_binding_id":"aeee4609-3ade-4002-af1a-e8f499b69a57","narrative_template_id":"61e18860-8c64-4740-8285-6b03fc343212"}],"step_key":"fase_4","triggers":[],"encounters":[]}],"schema_version":"mission-generic-definition/1"},"transitions":[{"priority":0,"event_kind":"inizio_avanti","to_step_key":"conclusione","from_step_key":"inizio","transition_key":"inizio_avanti"},{"priority":0,"event_kind":"conclusione_passaggio_5","to_step_key":"fase_3","from_step_key":"conclusione","transition_key":"conclusione_passaggio_5"},{"priority":0,"event_kind":"conclusione_passaggio_1","to_step_key":"fase_4","from_step_key":"conclusione","transition_key":"conclusione_passaggio_1"},{"priority":0,"event_kind":"fase_3_passaggio_6","to_step_key":"fase_4","from_step_key":"fase_3","transition_key":"fase_3_passaggio_6"}],"schema_version":"mission-generic-plan-document/1","terminal_steps":[{"outcome":"success","step_key":"fase_4"}],"initial_step_key":"inizio","base_plan_version_id":"4dc392b7-fad5-48c0-bd68-3b663e5595ac"},"arenas":[{"step_key":"fase_3","zone_key":"arena","template_key":"mission_map_konoha_piazza_mercato","template_version":1}],"mission":{"grado":"D","title":"Discussioni in Centro","village":"Konoha","briefing":"Nel centro di Konoha alcune persone discutono degli attacchi avvenuti fuori dal Villaggio. Le informazioni sono frammentarie, ma due giovani Genin sostengono di conoscere i responsabili. Verificate le loro affermazioni prima che le voci provochino disordini.","team_max":2,"team_min":2,"tag_trama":"Konoha · disinformazione · voci pagate · mandante ignoto","direction_mode":"ai","gathering_location_id":"658254ac-8c82-41cb-b190-01f3ecb993b4"},"editorial":{"scenes":[{"actors":[{"actor_key":"png_1","goal_private":"Influire sull’esito dell’incontro e sul modo in cui viene considerato; salvare la faccia può significare difendere la scelta, negoziare o compiere un atto concreto per rimediare.","role_in_phase":"Daichi, promotore spavaldo delle voci pagate; capannello iniziale","public_portrayal":"Daichi cerca spazio nel confronto e un modo di contare ancora, anche quando la sua versione perde sostegno. La voce è rivolta a un pubblico finché questo gli serve; può poi diventare diretta e negoziale.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. All’inizio dell’incontro Daichi conserva con sé il foglio ricevuto con le istruzioni e la propria parte delle monete. Non li ha ancora consegnati a nessuno."},{"actor_key":"png_2","goal_private":"Trovare una via praticabile che non lo lasci dipendente dalla versione di Daichi; può scegliere e mantenere un impegno personale.","role_in_phase":"Keita, complice esitante e influenzabile; capannello iniziale","public_portrayal":"Keita parte dall’intesa con Daichi ma cerca una posizione propria. Può spiegarsi a lungo o obiettare pur mantenendo un tono incerto; l’attenzione non è obbligata a tornare al compagno a ogni battuta.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. All’inizio dell’incontro Keita conserva con sé la propria parte delle monete ricevute. Il foglio con le istruzioni è rimasto a Daichi."}],"setting":{"name":"Centro di Konoha — piazza del mercato","description":"Il mercato occupa la piazza con banchi di legno segnati dall’uso, teli di stoffa sopra le merci e ceste basse accanto alle botteghe. Carta e spago servono a preparare gli acquisti; gli addetti hanno ordinazioni da finire e rifornimenti da sistemare. Chi trasporta un carico cerca un varco, chi attende di essere servito vuole raggiungere il banco, altri si fermano ad ascoltare i due Genin. Il capannello si trova fra queste attività e non assorbe tutta la piazza. Soglie, bordi dei banchi e tratti meno affollati offrono posizioni diverse per parlarsi o lasciar passare. Ogni attività ha una durata e una destinazione: un lavoro concluso o uno spostamento già avvenuto rimangono parte della situazione, anche quando l’attenzione torna al dialogo."},"step_key":"inizio","consequences":[{"public_fact":"I due giovani accettano il confronto e iniziano a esporre la propria versione.","private_note":"Passare al confronto quando le azioni dei PG aprono domande o proposte pertinenti, senza un ordine obbligato.","transition_key":"inizio_avanti"}],"entry_public":"Nella piazza del mercato di Konoha c’è un capannello attorno a due giovani Genin. Daichi Moro sostiene di conoscere i responsabili degli attacchi avvenuti fuori dal Villaggio; Keita Uro è con lui. Banchi e botteghe restano in attività attorno ai curiosi.","director_notes":"Questo è il primo incontro dei PG con il capannello. L’accusa circola nella piazza, ma fra i PG e i due Genin non è ancora avvenuto uno scambio: nessuna loro domanda, risposta o decisione precede questo quadro. Il contatto resta aperto alle scelte dei giocatori. Foglio e monete sono con i rispettivi possessori indicati nelle schede; non sono stati mostrati, consegnati o perduti. La prima iniziativa dei Genin parte da questa situazione, senza presupporre un colloquio già trascorso."},{"actors":[{"actor_key":"png_1","goal_private":"Influire sull’esito dell’incontro e sul modo in cui viene considerato; salvare la faccia può significare difendere la scelta, negoziare o compiere un atto concreto per rimediare.","role_in_phase":"Daichi, promotore spavaldo delle voci pagate; confronto aperto","public_portrayal":"Daichi cerca spazio nel confronto e un modo di contare ancora, anche quando la sua versione perde sostegno. La voce è rivolta a un pubblico finché questo gli serve; può poi diventare diretta e negoziale.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. All’inizio dell’incontro Daichi conserva con sé il foglio ricevuto con le istruzioni e la propria parte delle monete. Non li ha ancora consegnati a nessuno."},{"actor_key":"png_2","goal_private":"Trovare una via praticabile che non lo lasci dipendente dalla versione di Daichi; può scegliere e mantenere un impegno personale.","role_in_phase":"Keita, complice esitante e influenzabile; confronto aperto","public_portrayal":"Keita parte dall’intesa con Daichi ma cerca una posizione propria. Può spiegarsi a lungo o obiettare pur mantenendo un tono incerto; l’attenzione non è obbligata a tornare al compagno a ogni battuta.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. All’inizio dell’incontro Keita conserva con sé la propria parte delle monete ricevute. Il foglio con le istruzioni è rimasto a Daichi."}],"setting":{"name":"Centro di Konoha — piazza del mercato","description":"Il mercato occupa la piazza con banchi di legno segnati dall’uso, teli di stoffa sopra le merci e ceste basse accanto alle botteghe. Carta e spago servono a preparare gli acquisti; gli addetti hanno ordinazioni da finire e rifornimenti da sistemare. Chi trasporta un carico cerca un varco, chi attende di essere servito vuole raggiungere il banco, altri si fermano ad ascoltare i due Genin. Il capannello si trova fra queste attività e non assorbe tutta la piazza. Soglie, bordi dei banchi e tratti meno affollati offrono posizioni diverse per parlarsi o lasciar passare. Ogni attività ha una durata e una destinazione: un lavoro concluso o uno spostamento già avvenuto rimangono parte della situazione, anche quando l’attenzione torna al dialogo."},"step_key":"conclusione","consequences":[{"public_fact":"Il confronto sfocia in uno scontro: i presenti cercano spazio per mettersi al sicuro.","private_note":"Solo quando scelte effettive e fatti autorizzati motivano l'ingresso Combat; pagamento emerso o domanda insistente non impongono attacchi.","transition_key":"conclusione_passaggio_5"},{"public_fact":"Il confronto ha prodotto una scelta concreta per interrompere la diffusione dell’accusa e dare un seguito all’incontro.","private_note":"La transizione segue una ritrattazione, collaborazione o intesa effettivamente raggiunta con le azioni e le risposte; il seguito è giocabile senza ripetere le stesse conferme.","transition_key":"conclusione_passaggio_1"}],"entry_public":"Il colloquio prosegue fra i banchi: i due Genin hanno interlocutori diretti, mentre chi passa decide se fermarsi o continuare le proprie attività.","director_notes":"Il colloquio riguarda la provenienza dell’accusa, il coinvolgimento dei due e le scelte che vogliono compiere adesso. Daichi e Keita possono precisare un punto rimasto aperto, dissentire, chiedere qualcosa o dare seguito a una proposta. Le informazioni disponibili seguono le esperienze dei singoli, senza una sequenza obbligata di domande. Un’intesa effettiva apre il seguito pacifico; se le decisioni producono un conflitto, resta disponibile il passaggio allo scontro."},{"actors":[{"actor_key":"png_1","goal_private":"Influire sull’esito dell’incontro e sul modo in cui viene considerato; salvare la faccia può significare difendere la scelta, negoziare o compiere un atto concreto per rimediare.","role_in_phase":"Daichi, promotore spavaldo delle voci pagate; conflitto se effettivamente avviato","public_portrayal":"Daichi cerca spazio nel confronto e un modo di contare ancora, anche quando la sua versione perde sostegno. La voce è rivolta a un pubblico finché questo gli serve; può poi diventare diretta e negoziale.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. All’inizio dell’incontro Daichi conserva con sé il foglio ricevuto con le istruzioni e la propria parte delle monete. Non li ha ancora consegnati a nessuno."},{"actor_key":"png_2","goal_private":"Trovare una via praticabile che non lo lasci dipendente dalla versione di Daichi; può scegliere e mantenere un impegno personale.","role_in_phase":"Keita, complice esitante e influenzabile; conflitto se effettivamente avviato","public_portrayal":"Keita parte dall’intesa con Daichi ma cerca una posizione propria. Può spiegarsi a lungo o obiettare pur mantenendo un tono incerto; l’attenzione non è obbligata a tornare al compagno a ogni battuta.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. All’inizio dell’incontro Keita conserva con sé la propria parte delle monete ricevute. Il foglio con le istruzioni è rimasto a Daichi."}],"setting":{"name":"Centro di Konoha — piazza del mercato","description":"Il mercato occupa la piazza con banchi di legno segnati dall’uso, teli di stoffa sopra le merci e ceste basse accanto alle botteghe. Carta e spago servono a preparare gli acquisti; gli addetti hanno ordinazioni da finire e rifornimenti da sistemare. Chi trasporta un carico cerca un varco, chi attende di essere servito vuole raggiungere il banco, altri si fermano ad ascoltare i due Genin. Il capannello si trova fra queste attività e non assorbe tutta la piazza. Soglie, bordi dei banchi e tratti meno affollati offrono posizioni diverse per parlarsi o lasciar passare. Ogni attività ha una durata e una destinazione: un lavoro concluso o uno spostamento già avvenuto rimangono parte della situazione, anche quando l’attenzione torna al dialogo."},"step_key":"fase_3","consequences":[{"public_fact":"Lo scontro è terminato; chi resta nella piazza può dare seguito alle proprie decisioni.","private_note":"Usare soltanto combat_terminal_confirmed dell'incontro esistente, senza equiparare any alla sconfitta di entrambi o a una confessione.","transition_key":"fase_3_passaggio_6"}],"entry_public":"Il confronto ha lasciato spazio al conflitto nella piazza: occorre evitare che vi siano coinvolti i civili.","director_notes":"Conservare incontro, mappa e attori nativi. Le azioni meccaniche e gli esiti derivano soltanto dalle ricevute del server. I Genin usano le azioni comuni autorizzate, non tecniche. Durante il conflitto restano persone con interessi, risposte già date e possibilità di parlare o fermarsi: la fine dello scontro non determina una confessione. I civili e le attività della piazza mantengono le conseguenze osservabili già stabilite; nessun nuovo malus o esito meccanico viene dedotto dal colore ambientale."},{"actors":[{"actor_key":"png_1","goal_private":"Influire sull’esito dell’incontro e sul modo in cui viene considerato; salvare la faccia può significare difendere la scelta, negoziare o compiere un atto concreto per rimediare.","role_in_phase":"Daichi, promotore spavaldo delle voci pagate; seguito concreto dell’incontro","public_portrayal":"Daichi cerca spazio nel confronto e un modo di contare ancora, anche quando la sua versione perde sostegno. La voce è rivolta a un pubblico finché questo gli serve; può poi diventare diretta e negoziale.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. All’inizio dell’incontro Daichi conserva con sé il foglio ricevuto con le istruzioni e la propria parte delle monete. Non li ha ancora consegnati a nessuno."},{"actor_key":"png_2","goal_private":"Trovare una via praticabile che non lo lasci dipendente dalla versione di Daichi; può scegliere e mantenere un impegno personale.","role_in_phase":"Keita, complice esitante e influenzabile; seguito concreto dell’incontro","public_portrayal":"Keita parte dall’intesa con Daichi ma cerca una posizione propria. Può spiegarsi a lungo o obiettare pur mantenendo un tono incerto; l’attenzione non è obbligata a tornare al compagno a ogni battuta.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. All’inizio dell’incontro Keita conserva con sé la propria parte delle monete ricevute. Il foglio con le istruzioni è rimasto a Daichi."}],"setting":{"name":"Centro di Konoha — piazza del mercato","description":"Il mercato occupa la piazza con banchi di legno segnati dall’uso, teli di stoffa sopra le merci e ceste basse accanto alle botteghe. Carta e spago servono a preparare gli acquisti; gli addetti hanno ordinazioni da finire e rifornimenti da sistemare. Chi trasporta un carico cerca un varco, chi attende di essere servito vuole raggiungere il banco, altri si fermano ad ascoltare i due Genin. Il capannello si trova fra queste attività e non assorbe tutta la piazza. Soglie, bordi dei banchi e tratti meno affollati offrono posizioni diverse per parlarsi o lasciar passare. Ogni attività ha una durata e una destinazione: un lavoro concluso o uno spostamento già avvenuto rimangono parte della situazione, anche quando l’attenzione torna al dialogo."},"step_key":"fase_4","consequences":[],"entry_public":"Il confronto nella piazza ha raggiunto un esito; attorno agli interlocutori continuano le attività del mercato.","director_notes":"La fase dà seguito all’esito effettivo del confronto: rettifica pubblica, collaborazione o separazione degli interlocutori. Gli impegni già accettati lasciano spazio al loro seguito, senza un’altra assicurazione equivalente. Le eventuali consegne di foglio e monete e le loro destinazioni restano acquisite. L’incontro può terminare con il congedo o con lo spostamento concordato, mentre le attività vicine proseguono dal punto raggiunto."}],"setting":{"name":"Centro di Konoha — piazza del mercato","description":"Il mercato occupa la piazza con banchi di legno segnati dall’uso, teli di stoffa sopra le merci e ceste basse accanto alle botteghe. Carta e spago servono a preparare gli acquisti; gli addetti hanno ordinazioni da finire e rifornimenti da sistemare. Chi trasporta un carico cerca un varco, chi attende di essere servito vuole raggiungere il banco, altri si fermano ad ascoltare i due Genin. Il capannello si trova fra queste attività e non assorbe tutta la piazza. Soglie, bordi dei banchi e tratti meno affollati offrono posizioni diverse per parlarsi o lasciar passare. Ogni attività ha una durata e una destinazione: un lavoro concluso o uno spostamento già avvenuto rimangono parte della situazione, anche quando l’attenzione torna al dialogo."},"plot_private":"I due Genin hanno accettato monete e istruzioni scritte nella busta trovata sotto un banco vuoto dietro le botteghe alla chiusura del mercato, la sera precedente. Hanno diffuso la versione inventata sugli attacchi. Il denaro, il bisogno di attenzione e il rapporto tra i due spiegano il loro coinvolgimento, ma ognuno conserva interessi e scelte proprie. Il mandante non è stato incontrato; identità e verità degli attacchi rimangono fuori dalle loro conoscenze. Le informazioni che possiedono possono emergere quando lo scambio le rende pertinenti, attraverso risposte, obiezioni, proposte o iniziative autonome. Un’offerta praticabile può portare a rimediare anche senza scontro; accordi e ritrattazioni producono un seguito concreto nella scena. All’inizio Daichi conserva il foglio con le istruzioni e la propria parte delle monete; Keita conserva la propria parte delle monete. Sono oggetti della fiction narrativa: il loro possesso iniziale è distinto dall’ignoranza sull’identità del mandante e sulla verità degli attacchi. La loro posizione o disponibilità cambia soltanto con gli sviluppi effettivamente narrati, non per una dimenticanza del turno successivo."},"schema_version":"mission-creation-document/1"},"created_at":"2026-10-29T23:07:33.022915+00:00","created_by":"f0856d53-83a6-4de0-bc0c-12c87916e665","mission_id":"6d6c216a-222d-4cba-b2fc-f3e0c199c195","arena_sources":[{"origin":"mission_phase","catalog":{"slots":[],"objects":[],"template":{"status":"ready","width_m":10,"height_m":10,"template_key":"mission_map_konoha_piazza_mercato","geometry_hash":"d41d8cd98f00b204e9800998ecf8427e","actor_radius_m":0.5,"contract_version":"arena-template/general-v1","template_version":1,"required_shape_keys":[],"source_asset_sha256":"f181ce14a35b7b5b49df2c7694c93c984c53a0898b1a9b0457bbefc5cd751475","geometry_contract_id":"mission-general-map","geometry_contract_version":1}},"width_m":10,"height_m":10,"step_key":"fase_3","zone_key":"arena","frozen_at":"2026-10-29T23:07:32.934499+00:00","template_key":"mission_map_konoha_piazza_mercato","catalog_sha256":"82fe32eb8f08d2ace1bc06fccbbb7d022e8c616e529915043a60d82538011a2e","schema_version":"mission-arena-source/1","config_revision":1,"template_version":1}],"direction_mode":"ai","document_sha256":"c6bf5c7af04a3f2a68e1f47bb4a16a167d322a787393def4f0265edbfac2faf3","plan_version_id":"848a988d-5705-4304-a9e5-172e4e09c725","gathering_location_id":"658254ac-8c82-41cb-b190-01f3ecb993b4"},"selection":{"mission_id":"6d6c216a-222d-4cba-b2fc-f3e0c199c195","selected_at":"2026-10-29T23:07:33.031992+00:00","control_version":7,"plan_version_id":"848a988d-5705-4304-a9e5-172e4e09c725"},"templates":[{"id":"2317301f-2144-4a13-99d2-b6be0b9e75c9","created_at":"2026-09-21T19:29:22.2545+00:00","created_by":"b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b","updated_at":"2026-10-29T22:29:00.286379+00:00","request_key":"017dee0f-a58c-4291-88b0-ad3e13349314","display_name":"Daichi Moro","template_key":"daichi_moro","village_scope":"Konoha","deactivated_at":null,"control_version":25,"lifecycle_state":"approved","current_version_id":"aa345444-373e-47de-960e-e53da42029da"},{"id":"61e18860-8c64-4740-8285-6b03fc343212","created_at":"2026-09-21T19:32:3