6e0d234ccc050c85acf929131a843ff069"},"mission_snapshot":{"grado":"D","title":"Discussioni in Centro","status":"aperta","village":"Konoha","briefing":"Nel centro di Konoha alcune persone discutono degli attacchi avvenuti fuori dal Villaggio. Le informazioni sono frammentarie, ma due giovani Genin sostengono di conoscere i responsabili. Verificate le loro affermazioni prima che le voci provochino disordini.","team_max":2,"team_min":2,"tag_trama":"Konoha · disinformazione · voci pagate · mandante ignoto","xp_reward":40,"mission_id":"6d6c216a-222d-4cba-b2fc-f3e0c199c195","ryo_reward":50,"location_hint":"Konoha — Centro"},"media_adoptions":[{"receipt":{"scope":"staff_only","actor_id":"f0856d53-83a6-4de0-bc0c-12c87916e665","media_id":"b18688be-4083-404b-a029-63f6a8d2af23","binding_id":"d6bd425f-452a-46a1-b2a9-8dcef3caf542","template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9","approval_ref":"3e722352-967a-40b6-bdfc-e0c42830cdc1","media_sha256":"ad92896adb267b85651bb9f8f3e84d38e875be3717acc80b1e63213a8863ff28","approval_kind":"admin_approval","asset_version":1,"schema_version":"legacy-media-adoption/1","identity_sha256":"4bc7cb8cea6a43d51af729697376a0d379fd9997191893bcdb79ca79f473bf0c","new_content_sha256":"452f48874f199928b820f944c2b0c4de529d52084067016167569a6f8e3027c0","narrative_version_id":"aa345444-373e-47de-960e-e53da42029da","previous_content_sha256":"86cf868e9822d594f1fa587595aaad5bb684a6a5e39601e6f9b983ccd84b6138","previous_narrative_version_id":"b7c3b8b2-a368-4edf-845d-05b5445e33fc","original_narrative_approved_at":"2026-10-29T22:29:00.279256+00:00","original_narrative_approved_by":"f0856d53-83a6-4de0-bc0c-12c87916e665"},"actor_id":"f0856d53-83a6-4de0-bc0c-12c87916e665","media_id":"b18688be-4083-404b-a029-63f6a8d2af23","binding_id":"d6bd425f-452a-46a1-b2a9-8dcef3caf542","created_at":"2026-10-29T22:29:00.329756+00:00","template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9","approval_ref":"3e722352-967a-40b6-bdfc-e0c42830cdc1","media_sha256":"ad92896adb267b85651bb9f8f