versari","actor_key":"png_1","narrative_version_id":"68258768-8041-5b13-8588-055d208fe3d3","mechanical_binding_id":"1a52b6b2-8f00-5649-bfa4-5e5a5460f704","narrative_template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9"},{"team":"avversari","actor_key":"png_2","narrative_version_id":"6290f1da-cd33-5f56-8146-91f770d98e52","mechanical_binding_id":"00854ee7-b31e-5ff3-9ce0-797841873a81","narrative_template_id":"61e18860-8c64-4740-8285-6b03fc343212"}],"step_key":"conclusione","triggers":[{"label":"Affrontare lo scontro se il confronto degenera","fact_code":"player_choice_confirmed","source_kind":"player_choice","trigger_key":"passaggio_5","transition_key":"conclusione_passaggio_5"},{"label":"Concludere il confronto senza scontro","fact_code":"player_choice_confirmed","source_kind":"player_choice","trigger_key":"passaggio_1","transition_key":"conclusione_passaggio_1"}],"encounters":[]},{"actors":[{"team":"avversari","actor_key":"png_1","narrative_version_id":"68258768-8041-5b13-8588-055d208fe3d3","mechanical_binding_id":"1a52b6b2-8f00-5649-bfa4-5e5a5460f704","narrative_template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9"},{"team":"avversari","actor_key":"png_2","narrative_version_id":"6290f1da-cd33-5f56-8146-91f770d98e52","mechanical_binding_id":"00854ee7-b31e-5ff3-9ce0-797841873a81","narrative_template_id":"61e18860-8c64-4740-8285-6b03fc343212"}],"step_key":"fase_3","triggers":[{"label":"Mettere in sicurezza la piazza","fact_code":"combat_terminal_confirmed","source_kind":"combat_terminal","trigger_key":"passaggio_6","encounter_key":"enc_fase_3","combat_outcome":"any","transition_key":"fase_3_passaggio_6"}],"encounters":[{"actors":[{"team":"avversari","actor_key":"png_1","narrative_version_id":"68258768-8041-5b13-8588-055d208fe3d3","mechanical_binding_id":"1a52b6b2-8f00-5649-bfa4-5e5a5460f704","narrative_template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9"},{"team":"avversari","actor_key":"png_2","narrative_version_id":"6290f1da-cd33-5f56-8146-91f770d98e52","mechanical_binding_id":"00854ee7-b31e-5ff3-9ce0-797841873a81","narrative_template_id":"61e18860-8c64-4740-8285-6b03fc343212"}],"pg_team":"squadra","arena_ref":"mission","pg_policy":"all_active","encounter_key":"enc_fase_3"}]},{"actors":[{"team":"avversari","actor_key":"png_1","narrative_version_id":"68258768-8041-5b13-8588-055d208fe3d3","mechanical_binding_id":"1a52b6b2-8f00-5649-bfa4-5e5a5460f704","narrative_template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9"},{"team":"avversari","actor_key":"png_2","narrative_version_id":"6290f1da-cd33-5f56-8146-91f770d98e52","mechanical_binding_id":"00854ee7-b31e-5ff3-9ce0-797841873a81","narrative_template_id":"61e18860-8c64-4740-8285-6b03fc343212"}],"step_key":"fase_4","triggers":[],"encounters":[]}],"schema_version":"mission-generic-definition/1"},"transitions":[{"priority":0,"event_kind":"inizio_avanti","to_step_key":"conclusione","from_step_key":"inizio","transition_key":"inizio_avanti"},{"priority":0,"event_kind":"conclusione_passaggio_5","to_step_key":"fase_3","from_step_key":"conclusione","transition_key":"conclusione_passaggio_5"},{"priority":0,"event_kind":"conclusione_passaggio_1","to_step_key":"fase_4","from_step_key":"conclusione","transition_key":"conclusione_passaggio_1"},{"priority":0,"event_kind":"fase_3_passaggio_6","to_step_key":"fase_4","from_step_key":"fase_3","transition_key":"fase_3_passaggio_6"}],"schema_version":"mission-generic-plan-document/1","terminal_steps":[{"outcome":"success","step_key":"fase_4"}],"initial_step_key":"inizio","base_plan_version_id":"848a988d-5705-4304-a9e5-172e4e09c725"},"arenas":[{"step_key":"fase_3","zone_key":"arena","template_key":"mission_map_konoha_piazza_mercato","template_version":1}],"mission":{"grado":"D","title":"Discussioni in Centro","village":"Konoha","briefing":"Nel centro di Konoha alcune persone discutono degli attacchi avvenuti fuori dal Villaggio. Le informazioni sono frammentarie, ma due giovani Genin sostengono di conoscere i responsabili. Verificate le loro affermazioni prima che le voci provochino disordini.","team_max":2,"team_min":2,"tag_trama":"Konoha · disinformazione · voci pagate · mandante ignoto","direction_mode":"ai","gathering_location_id":"658254ac-8c82-41cb-b190-01f3ecb993b4"},"editorial":{"scenes":[{"actors":[{"actor_key":"png_1","goal_private":"Trovare un interlocutore e spazio per sostenere la versione che sta diffondendo.","role_in_phase":"Daichi, promotore spavaldo delle voci pagate; capannello iniziale","public_portrayal":"Daichi cerca un pubblico nell’attenzione dei curiosi; può rivolgersi a un nuovo interlocutore quando entra nello scambio. Il suo modo di presentarsi nasce da questa ricerca di peso nella piazza.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. All’inizio dell’incontro Daichi conserva con sé il foglio ricevuto con le istruzioni e la propria parte delle monete. Non li ha ancora consegnati a nessuno."},{"actor_key":"png_2","goal_private":"Esporre la propria partecipazione al capannello trovando un rapporto diretto con chi gli si rivolge.","role_in_phase":"Keita, complice esitante e influenzabile; capannello iniziale","public_portrayal":"Keita partecipa al capannello con Daichi, ma un interlocutore diretto gli permette di mettere a fuoco ciò che pensa e ciò che ha fatto in prima persona.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. All’inizio dell’incontro Keita conserva con sé la propria parte delle monete ricevute. Il foglio con le istruzioni è rimasto a Daichi."}],"setting":{"name":"Centro di Konoha — piazza del mercato","description":"La piazza contiene il lavoro del mercato oltre al capannello: merci sui banchi di legno, teli sopra gli acquisti, ceste e passaggi fra le botteghe. Gli addetti hanno scambi da completare e carichi da sistemare; i curiosi si fermano dentro questo movimento. Le distanze fra le voci, chi ascolta e chi deve passare rendono concreto il primo contatto."},"step_key":"inizio","consequences":[{"public_fact":"I due giovani accettano il confronto e iniziano a esporre la propria versione.","private_note":"Passare al confronto quando le azioni dei PG aprono domande o proposte pertinenti, senza un ordine obbligato.","transition_key":"inizio_avanti"}],"entry_public":"Nella piazza del mercato di Konoha c’è un capannello attorno a due giovani Genin. Daichi Moro sostiene di conoscere i responsabili degli attacchi avvenuti fuori dal Villaggio; Keita Uro è con lui. Banchi e botteghe restano in attività attorno ai curiosi.","director_notes":"È il primo contatto dei PG con il capannello. Le iniziative dei due Genin e le attività già presenti offrono interlocutori e uno spazio in cui muoversi; lo scambio nasce dalle scelte effettive dei presenti. Foglio e monete sono ancora presso i possessori iniziali. L’ambiente può entrare nel contatto attraverso ciò che le persone stanno facendo, non richiede una descrizione separata prima del dialogo."},{"actors":[{"actor_key":"png_1","goal_private":"Salvare ciò che ancora gli importa attraverso la scelta aperta adesso e un seguito che può effettivamente compiere.","role_in_phase":"Daichi, promotore spavaldo delle voci pagate; confronto aperto","public_portrayal":"Daichi si misura con il punto sollevato ora: può difendere un dettaglio, precisare una responsabilità o trattare un seguito concreto. L’attenzione del pubblico resta utile solo finché sostiene ciò che sta cercando di ottenere.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. La disponibilità attuale di foglio e monete segue le consegne e gli sviluppi già avvenuti nel confronto."},{"actor_key":"png_2","goal_private":"Trovare una direzione personale nel problema presente e portare avanti ciò che ha scelto.","role_in_phase":"Keita, complice esitante e influenzabile; confronto aperto","public_portrayal":"Keita prende posizione sul tema presente e può motivare una scelta propria, anche diversa da quella di Daichi. La voce incerta non gli impedisce di aggiungere un particolare che conosce o rivolgere una domanda precisa.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. La disponibilità attuale di foglio e monete segue le consegne e gli sviluppi già avvenuti nel confronto."}],"setting":{"name":"Centro di Konoha — piazza del mercato","description":"Il colloquio occupa una parte della piazza, mentre il mercato ha ritmi e occupazioni propri. Un acquisto o un carico già seguito nella scena conserva il punto a cui è arrivato: lo spazio e l’attenzione disponibili dipendono da questi sviluppi. Il lavoro vicino può incrociare il dialogo e orientare dove ci si parla, chi riesce a sentire e a chi è rivolta una risposta, senza sostituire il confronto con una nuova panoramica."},"step_key":"conclusione","consequences":[{"public_fact":"Il confronto sfocia in uno scontro: i presenti cercano spazio per mettersi al sicuro.","private_note":"Solo quando scelte effettive e fatti autorizzati motivano l'ingresso Combat; pagamento emerso o domanda insistente non impongono attacchi.","transition_key":"conclusione_passaggio_5"},{"public_fact":"Il confronto ha prodotto una scelta concreta per interrompere la diffusione dell’accusa e dare un seguito all’incontro.","private_note":"La transizione segue una ritrattazione, collaborazione o intesa effettivamente raggiunta con le azioni e le risposte; il seguito è giocabile senza ripetere le stesse conferme.","transition_key":"conclusione_passaggio_1"}],"entry_public":"Il colloquio prosegue fra i banchi: i due Genin hanno interlocutori diretti, mentre chi passa decide se fermarsi o continuare le proprie attività.","director_notes":"Il punto aperto del colloquio orienta le risposte: fonte delle accuse, responsabilità, dissensi o proposta attuale. Un chiarimento acquisito rende possibile una domanda diversa, una conseguenza o una scelta concreta. I Genin hanno interessi propri e possono rispondere tra loro oltre che ai PG; un impegno già assunto produce il suo seguito. Lo spazio e le attività attorno al gruppo incidono sul modo in cui il confronto si svolge, restando coerenti con quanto è già accaduto. Le vie pacifica e conflittuale rimangono possibilità legate alle scelte reali."},{"actors":[{"actor_key":"png_1","goal_private":"Salvare ciò che ancora gli importa attraverso la scelta aperta adesso e un seguito che può effettivamente compiere.","role_in_phase":"Daichi, promotore spavaldo delle voci pagate; conflitto se effettivamente avviato","public_portrayal":"Daichi reagisce al pericolo e alle possibilità effettive dello scontro. Le sue parole riguardano ciò che sta succedendo e gli interessi rimasti aperti; orgoglio, timore o disponibilità emergono dal comportamento corrente.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. La disponibilità attuale di foglio e monete segue le consegne e gli sviluppi già avvenuti nel confronto."},{"actor_key":"png_2","goal_private":"Trovare una direzione personale nel problema presente e portare avanti ciò che ha scelto.","role_in_phase":"Keita, complice esitante e influenzabile; conflitto se effettivamente avviato","public_portrayal":"Keita affronta il conflitto con la posizione personale maturata nel dialogo. Può rispondere a un’offerta o mostrare il proprio dissenso secondo ciò che sta avvenendo, senza assumere che il compagno scelga allo stesso modo.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. La disponibilità attuale di foglio e monete segue le consegne e gli sviluppi già avvenuti nel confronto."}],"setting":{"name":"Centro di Konoha — piazza del mercato","description":"Lo spazio è la piazza già raggiunta: banchi, teli, merci, varchi e persone conservano le posizioni e le conseguenze stabilite. Nel conflitto suoni, respiro, distanze e attività interrotte accompagnano i fatti attestati dello scontro. Ciò che i civili hanno già fatto e le occupazioni lasciate in sospeso mantengono continuità; il colore del luogo non modifica posizioni, ripari o conseguenze meccaniche."},"step_key":"fase_3","consequences":[{"public_fact":"Lo scontro è terminato; chi resta nella piazza può dare seguito alle proprie decisioni.","private_note":"Usare soltanto combat_terminal_confirmed dell'incontro esistente, senza equiparare any alla sconfitta di entrambi o a una confessione.","transition_key":"fase_3_passaggio_6"}],"entry_public":"Il confronto ha lasciato spazio al conflitto nella piazza: occorre evitare che vi siano coinvolti i civili.","director_notes":"Incontro, mappa, turni e fatti meccanici sono quelli nativi del server. Il dialogo mantiene ciò che i presenti hanno imparato e deciso prima dello scontro. Un intervento dei Genin risponde all’azione o alla proposta attuale e può cambiare la loro disposizione senza ripercorrere l’intero confronto. Piazza, civili e lavoro interrotto danno profondità ai fatti risolti; non introducono danni, malus o manovre ulteriori."},{"actors":[{"actor_key":"png_1","goal_private":"Salvare ciò che ancora gli importa attraverso la scelta aperta adesso e un seguito che può effettivamente compiere.","role_in_phase":"Daichi, promotore spavaldo delle voci pagate; seguito concreto dell’incontro","public_portrayal":"Daichi dà seguito alla decisione raggiunta attraverso un comportamento osservabile o una risposta a ciò che resta da definire. Il modo in cui conclude l’incontro può conservare il suo orgoglio e cambiare il rapporto con chi ha davanti.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. La disponibilità attuale di foglio e monete segue le consegne e gli sviluppi già avvenuti nel confronto."},{"actor_key":"png_2","goal_private":"Trovare una direzione personale nel problema presente e portare avanti ciò che ha scelto.","role_in_phase":"Keita, complice esitante e influenzabile; seguito concreto dell’incontro","public_portrayal":"Keita porta avanti ciò che ha scelto in prima persona. Può congedarsi o collaborare mantenendo una sfumatura emotiva propria; il seguito dell’impegno rende leggibile la sua posizione senza un nuovo riepilogo.","known_facts_private":"La sera precedente, alla chiusura del mercato, entrambi hanno ricevuto una busta con monete e un foglio sotto un banco vuoto dietro le botteghe. Sul foglio c’erano le frasi da ripetere sugli attacchi; entrambi hanno accettato il denaro e partecipato alla diffusione della storia. Le accuse non derivano da una loro testimonianza diretta o da riscontri: la fonte personale raccontata da Daichi appartiene alla versione inventata. Conoscenze assenti: Identità, organizzazione e intenzioni di chi ha lasciato la busta; verità, dinamica e responsabili degli attacchi. Non ha incontrato il mandante e non possiede elementi per identificarlo. La disponibilità attuale di foglio e monete segue le consegne e gli sviluppi già avvenuti nel confronto."}],"setting":{"name":"Centro di Konoha — piazza del mercato","description":"Il seguito avviene nella stessa piazza, con le persone e le attività al punto raggiunto durante l’incontro. Acquisti, carichi, passaggi e conversazioni già introdotti possono arrivare a compimento o restare interrotti secondo quanto è accaduto. Un congedo, una consegna o uno spostamento concordato si inseriscono in questo corso concreto del luogo, rendendo visibile ciò che la conclusione cambia."},"step_key":"fase_4","consequences":[],"entry_public":"Il confronto nella piazza ha raggiunto un esito; attorno agli interlocutori continuano le attività del mercato.","director_notes":"La conclusione mette in atto il seguito dell’esito raggiunto. Responsabilità e impegni già chiariti restano acquisiti: la scena può mostrare ciò che viene fatto, come si ridefiniscono i rapporti o come gli interlocutori si separano. Custodia di foglio e monete, accordi, spostamenti e attività del mercato continuano dal punto effettivo; ogni nuova battuta si rivolge a un punto ancora aperto. Il congedo non richiede una seconda dichiarazione equivalente di disponibilità."}],"setting":{"name":"Centro di Konoha — piazza del mercato","description":"La piazza del mercato di Konoha è uno spazio di lavoro e di passaggio: banchi di legno segnati dall’uso, teli sopra le merci, ceste basse presso le botteghe, carta e spago per gli acquisti. Le persone hanno attività e destinazioni proprie. Posizioni, oggetti e lavori seguono gli sviluppi della scena; l’attenzione al capannello convive con il resto della piazza."},"plot_private":"I due Genin hanno accettato monete e istruzioni scritte nella busta trovata sotto un banco vuoto dietro le botteghe alla chiusura del mercato, la sera precedente. Hanno diffuso la versione inventata sugli attacchi. Il denaro, il bisogno di attenzione e il rapporto tra i due spiegano il loro coinvolgimento, ma ognuno conserva interessi e scelte proprie. Il mandante non è stato incontrato; identità e verità degli attacchi rimangono fuori dalle loro conoscenze. Le informazioni che possiedono possono emergere quando lo scambio le rende pertinenti, attraverso risposte, obiezioni, proposte o iniziative autonome. Un’offerta praticabile può portare a rimediare anche senza scontro; accordi e ritrattazioni producono un seguito concreto nella scena. All’inizio Daichi conserva il foglio con le istruzioni e la propria parte delle monete; Keita conserva la propria parte delle monete. Sono oggetti della fiction narrativa: il loro possesso iniziale è distinto dall’ignoranza sull’identità del mandante e sulla verità degli attacchi. La loro posizione o disponibilità cambia soltanto con gli sviluppi effettivamente narrati, non per una dimenticanza del turno successivo."},"schema_version":"mission-creation-document/1"},"definition":{"scenes":[{"actors":[{"team":"avversari","actor_key":"png_1","narrative_version_id":"68258768-8041-5b13-8588-055d208fe3d3","mechanical_binding_id":"1a52b6b2-8f00-5649-bfa4-5e5a5460f704","narrative_template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9"},{"team":"avversari","actor_key":"png_2","narrative_version_id":"6290f1da-cd33-5f56-8146-91f770d98e52","mechanical_binding_id":"00854ee7-b31e-5ff3-9ce0-797841873a81","narrative_template_id":"61e18860-8c64-4740-8285-6b03fc343212"}],"step_key":"inizio","triggers":[{"label":"Interrogare i due Genin","fact_code":"player_choice_confirmed","source_kind":"player_choice","trigger_key":"avanti","transition_key":"inizio_avanti"}],"encounters":[]},{"actors":[{"team":"avversari","actor_key":"png_1","narrative_version_id":"68258768-8041-5b13-8588-055d208fe3d3","mechanical_binding_id":"1a52b6b2-8f00-5649-bfa4-5e5a5460f704","narrative_template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9"},{"team":"avversari","actor_key":"png_2","narrative_version_id":"6290f1da-cd33-5f56-8146-91f770d98e52","mechanical_binding_id":"00854ee7-b31e-5ff3-9ce0-797841873a81","narrative_template_id":"61e18860-8c64-4740-8285-6b03fc343212"}],"step_key":"conclusione","triggers":[{"label":"Affrontare lo scontro se il confronto degenera","fact_code":"player_choice_confirmed","source_kind":"player_choice","trigger_key":"passaggio_5","transition_key":"conclusione_passaggio_5"},{"label":"Concludere il confronto senza scontro","fact_code":"player_choice_confirmed","source_kind":"player_choice","trigger_key":"passaggio_1","transition_key":"conclusione_passaggio_1"}],"encounters":[]},{"actors":[{"team":"avversari","actor_key":"png_1","narrative_version_id":"68258768-8041-5b13-8588-055d208fe3d3","mechanical_binding_id":"1a52b6b2-8f00-5649-bfa4-5e5a5460f704","narrative_template_id":"2317301f-2144-4a13-99d2-b6be0b9e75c9"},{"team":"avversari","actor_key":"png_2","narrative_version_id":"6290f1da-cd33-5f56-8146-91f770d98e52","mechanical_binding_id":"00854ee7-b31e-5ff3-9ce0-797841873a81","narrative_template_id":"61e18860-8c64-4740-8285-6b03fc343212"}],"step_key":"fase_3","triggers":[{"label":"Mettere in sicurezza la piazza","fact_code":"combat_terminal_confirmed","source_kind":"combat_terminal","trigger_key":"passaggio_6","encounter_ke