 SELECT jsonb_build_object('public_launch',mission_public_owner.is_public_launch_v1((e67_packet#>>'{before,selection,mission_id}')::uuid),'generic_mode',(SELECT mode FROM mission_generic_owner.runtime_policy WHERE singleton),'capabilities',(SELECT jsonb_agg(jsonb_build_object('state',state,'config_version',config_version))FROM mission_launch_owner.capabilities WHERE mission_id=(e67_packet#>>'{before,selection,mission_id}')::uuid),'dual_scopes',(SELECT count(*)FROM mission_launch_owner.dual_scopes WHERE mission_id=(e67_packet#>>'{before,selection,mission_id}')::uuid),'activations',(SELECT count(*)FROM mission_ai_board_owner.activations WHERE mission_id=(e67_packet#>>'{before,selection,mission_id}')::uuid),'open_publication',(SELECT count(*)FROM mission_public_owner.publications_v2 WHERE mission_id=(e67_packet#>>'{before,selection,mission_id}')::uuid AND target='public'AND visibility='open'AND state='open'))INTO e67_actual;
 IF e67_actual IS DISTINCT FROM e67_packet->'availability_before'THEN RAISE EXCEPTION 'E67_AVAILABILITY_DRIFT';END IF;
 FOR e67_item IN SELECT value FROM jsonb_array_elements(e67_packet->'dependency_ddl_md5')LOOP
 IF md5(pg_get_functiondef(to_regprocedure(e67_item->>'signature')))IS DISTINCT FROM e67_item->>'ddl_md5'THEN RAISE EXCEPTION 'E67_HELPER_DEPENDENCY_DRIFT %',e67_item->>'signature';END IF;END LOOP;
 FOR e67_item IN SELECT value FROM jsonb_array_elements(e67_packet->'authoring_metadata')LOOP
 SELECT jsonb_build_object('relation',n.nspname||'.'||c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid))ORDER BY a.attnum)FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid),'validated',convalidated)ORDER BY conname)FROM pg_constraint WHERE conrelid=c.oid),'indexes',(SELECT jsonb_agg(pg_get_indexdef(indexrelid)ORDER BY indexrelid::regclass::text)FROM pg_index WHERE indrelid=c.oid),'triggers',(SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled)ORDER BY t.tgname)FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal))INTO e67_actual FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid=to_regclass(e67_item->>'relation');
 IF e67_actual IS DISTINCT FROM e67_item THEN RAISE EXCEPTION 'E67_AUTHORING_SCHEMA_DRIFT %',e67_item->>'relation';END IF;END LOOP;
 FOR e67_item IN SELECT value FROM jsonb_array_elements(e67_base::jsonb#>'{db_core,all_function_headers}')LOOP e67_sig:=e67_item->>'signature';SELECT jsonb_build_object('signature',e67_sig,'oid',p.oid::bigint,'owner',pg_catalog.pg_get_userbyid(p.proowner),
 'acl',p.proacl::text,'config',to_jsonb(p.proconfig),'secdef',p.prosecdef,'language',l.lanname,
 'volatility',p.provolatile::text,'source_md5',pg_catalog.md5(p.prosrc),'ddl_md5',pg_catalog.md5(pg_catalog.pg_get_functiondef(p.oid)))
 INTO e67_actual FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_language l ON l.oid=p.prolang WHERE p.oid=pg_catalog.to_regprocedure(e67_sig);
 IF e67_actual IS DISTINCT FROM e67_item THEN RAISE EXCEPTION 'E67_HEADER_DRIFT %',e67_sig;END IF;END LOOP;
 FOR e67_item IN SELECT value FROM jsonb_array_elements(e67_abis)LOOP e67_sig:=e67_item->>'signature';SELECT jsonb_build_object('return_type',p.prorettype::regtype::text,'retset',p.proretset,'kind',p.prokind::text,'strict',p.proisstrict,'parallel',p.proparallel::text,'leakproof',p.proleakproof,'argument_names',coalesce(to_jsonb(p.proargnames),'[]'::jsonb),'argument_defaults_count',p.pronargdefaults,'argument_defaults_sql',pg_catalog.pg_get_expr(p.proargdefaults,0),'argument_modes',to_jsonb(coalesce(p.proargmodes,array_fill('i'::"char",ARRAY[p.pronargs::integer]))),'argument_count',p.pronargs,'variadic_type',p.provariadic::bigint,'cost',p.procost,'rows',p.prorows,'support_oid',p.prosupport::bigint) INTO e67_abi FROM pg_proc p WHERE p.oid=to_regprocedure(e67_sig);
 IF e67_abi IS DISTINCT FROM e67_item->'abi'THEN RAISE EXCEPTION 'E67_ABI_DRIFT %',e67_sig;END IF;END LOOP;
