 WITH runs AS(SELECT * FROM mission_narrative_internal.editorial_runs_v1 WHERE campaign_id='23c83d81-3e37-5a7e-8056-45b009992a3f'),calls AS(SELECT q.id,q.source_id,q.call_no,q.state,q.model,q.reserved_usd,q.charged_usd,q.input_tokens,q.output_tokens,q.created_at,q.sent_at,q.settled_at FROM staff_ai_quota_private.calls q WHERE q.scope_id='23c83d81-3e37-5a7e-8056-45b009992a3f'AND q.producer='mission_editorial_preview'),receipts AS(SELECT d.id,d.authority_receipt_id,d.status,d.dispatch_count,d.request_key,d.envelope->>'stage' AS stage,d.envelope_sha256=public.combat_v2_sha256(d.envelope)envelope_hash_valid,d.charged_cost_usd,d.created_at,d.finalized_at FROM mission_narrative_internal.dispatch_receipts d WHERE d.id IN(SELECT receipt_id FROM runs)),attempts AS(SELECT a.id,a.receipt_id,a.status,a.cost_basis,a.actual_cost_usd,a.input_tokens,a.output_tokens,a.reasoning_tokens,a.finalized_at FROM mission_narrative_internal.dispatch_attempts a WHERE a.receipt_id IN(SELECT receipt_id FROM runs)),authorizations AS(SELECT z.id,z.receipt_id,z.attempt_id,z.created_at,z.expires_at,z.consumed_at FROM mission_narrative_internal.provider_authorizations z WHERE z.receipt_id IN(SELECT receipt_id FROM runs))SELECT jsonb_build_object('calls',(SELECT jsonb_agg(to_jsonb(q)ORDER BY id)FROM calls q),'receipts',(SELECT jsonb_agg(to_jsonb(q)ORDER BY id)FROM receipts q),'attempts',(SELECT jsonb_agg(to_jsonb(q)ORDER BY id)FROM attempts q),'authorizations',(SELECT jsonb_agg(to_jsonb(q)ORDER BY id)FROM authorizations q),'audit',(SELECT jsonb_agg(jsonb_build_object('id',a.id,'receipt_id',a.receipt_id,'event_code',a.event_code,'details_sha256',public.combat_v2_sha256(a.details),'created_at',a.created_at)ORDER BY a.id)FROM mission_narrative_internal.dispatch_audit a WHERE a.receipt_id IN(SELECT receipt_id FROM runs)), 'count_http',(SELECT count(*) FROM calls WHERE call_no=2 AND state<>'no_http'),'generation_http',(SELECT count(*)FROM calls WHERE call_no=1 AND state<>'no_http'),'count_reserved_usd',(SELECT sum(reserved_usd)FROM calls WHERE call_no=2 AND state='unknown_billable'),'generation_exact_usd',(SELECT sum(charged_usd)FROM calls WHERE call_no=1 AND state IN('settled','over_cap')),'prudent_usd',(SELECT sum(CASE WHEN state IN('settled','over_cap')THEN charged_usd WHEN state='no_http'THEN 0 ELSE reserved_usd END)FROM calls),'run_sha256',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(r)ORDER BY id))FROM runs r),'quota_sha256',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(q)ORDER BY id))FROM staff_ai_quota_private.calls q WHERE scope_id='23c83d81-3e37-5a7e-8056-45b009992a3f'),'audit_sha256',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(a)ORDER BY id))FROM mission_narrative_internal.editorial_audit_v1 a WHERE run_id IN(SELECT id FROM runs)),
'dispatch_sha256',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(d)ORDER BY id))FROM mission_narrative_internal.dispatch_receipts d WHERE id IN(SELECT receipt_id FROM runs)),
'attempt_sha256',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(a)ORDER BY id))FROM mission_narrative_internal.dispatch_attempts a WHERE receipt_id IN(SELECT receipt_id FROM runs)),
'authorization_sha256',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(z)ORDER BY id))FROM mission_narrative_internal.provider_authorizations z WHERE receipt_id IN(SELECT receipt_id FROM runs)),
'dispatch_audit_sha256',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(a)ORDER BY id))FROM mission_narrative_internal.dispatch_audit a WHERE receipt_id IN(SELECT receipt_id FROM runs)))INTO e67_data;
